```cpp
#include <iostream>
#include <fstream>
using namespace std;

int sumaCyfr(int n) {
    int suma = 0;
    while (n > 0) {
        suma += n % 10;
        n /= 10;
    }
    return suma;
}

int nwd(int a, int b) {
    while (b != 0) { int t = b; b = a % b; a = t; }
    return a;
}

int main() {
    ifstream plik("pary.txt");
    int a, b;
    int ile = 0;
    while (plik >> a >> b) {
        int sa = sumaCyfr(a), sb = sumaCyfr(b);
        int g = nwd(sa, sb);
        cout << a << " i " << b << ": sumy cyfr = " << sa << " i " << sb << ", NWD = " << g << endl;
        if (g > 4) ile++;
    }
    cout << "Pary z NWD sum cyfr > 4: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Wieloetapowe przetwarzanie: (1) sumowanie cyfr obu liczb, (2) NWD tych sum algorytmem Euklidesa, (3) zliczanie par spelniajacych warunek.

